homepage.query:
    query homepage($relativePath: String!) {
  homepage(relativePath: $relativePath) {
    ... on Document {
      _sys {
        filename
        basename
        hasReferences
        breadcrumbs
        path
        relativePath
        extension
      }
      id
    }
    ...HomepageParts
  }
}

    fragment HomepageParts on Homepage {
  __typename
  hero {
    __typename
    location
    title
    accent
    description
    logo
    logoAlt
  }
  experiences {
    __typename
    eyebrow
    title
    accent
    intro
  }
  featuredTours {
    __typename
    eyebrow
    title
    accent
    intro
    tourNames
  }
  journey {
    __typename
    eyebrow
    title
    accent
    intro
    items {
      __typename
      icon
      label
      description
    }
  }
  guides {
    __typename
    eyebrow
    title
    accent
    items {
      __typename
      name
      role
      description
      image
      imageAlt
    }
  }
  about {
    __typename
    eyebrow
    titleLine1
    titleLine2
    titleAccent
    paragraphs
    quote
    image
    imageAlt
    badgeValue
    badgeText
  }
  gallery {
    __typename
    eyebrow
    title
    accent
    intro
    images {
      __typename
      image
      alt
      layout
    }
  }
  included {
    __typename
    title
    accent
    intro
    items {
      __typename
      icon
      label
    }
    note
  }
  faq {
    __typename
    eyebrow
    title
    items {
      __typename
      question
      answer
    }
  }
  contact {
    __typename
    eyebrow
    title
    accent
    intro
  }
}

